//! Dialect operation and type utilities.
//!
//! Provides `DialectOp`, `Verify`, and `DialectType` traits for arena-based
//! dialect operation and type wrappers, plus `ConversionError` and the
//! `raw_ident_str!` macro.
//! Trait definitions are generated by `trunk_ir_macros::dialect!`.

use std::error::Error;

use super::context::IrContext;
use super::op_def::{OpDef, OpName};
use super::refs::{OpRef, TypeRef};
use super::type_def::{TypeDef, TypeName};

/// Convert an identifier token into a clean string, handling raw identifiers.
///
/// Rust requires the `r#` prefix for reserved keywords like `type` or `yield`
/// when used as identifiers. This macro strips that prefix at expansion time
/// so the IR stores clean names like "type" instead of "r#type".
#[doc(hidden)]
#[macro_export]
macro_rules! raw_ident_str {
    (r#type) => {
        "type"
    };
    (r#const) => {
        "const"
    };
    (r#use) => {
        "use"
    };
    (r#yield) => {
        "yield"
    };
    (r#return) => {
        "return"
    };
    (r#if) => {
        "if"
    };
    (r#else) => {
        "else"
    };
    (r#loop) => {
        "loop"
    };
    (r#case) => {
        "case"
    };
    (r#struct) => {
        "struct"
    };
    (r#enum) => {
        "enum"
    };
    (r#break) => {
        "break"
    };
    (r#continue) => {
        "continue"
    };
    (r#ref) => {
        "ref"
    };
    ($ident:ident) => {
        stringify!($ident)
    };
}

/// Error when converting an Operation to a dialect-specific type.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ConversionError {
    /// The operation is not the expected one.
    WrongOperation { expected: OpName, actual: OpName },
    /// Missing required attribute.
    MissingAttribute(&'static str),
    /// Attribute has wrong type.
    WrongAttributeType(&'static str),
    /// Missing result type.
    MissingResult,
    /// Missing region.
    MissingRegion,
    /// Missing or insufficient successors.
    MissingSuccessor,
    /// Wrong number of operands.
    WrongOperandCount { expected: usize, actual: usize },
}

/// Trait for arena-based dialect operation wrappers.
pub trait DialectOp: Sized + Copy {
    /// Definition generated from the dialect declaration.
    const DEF: &'static OpDef;
    /// The operation's name, which points to [`DEF`](Self::DEF).
    const NAME: OpName = OpName::registered(Self::DEF);

    fn from_op(ctx: &IrContext, op: OpRef) -> Result<Self, ConversionError>;
    fn op_ref(&self) -> OpRef;

    fn matches(ctx: &IrContext, op: OpRef) -> bool {
        ctx.op(op).name == Self::NAME
    }
}

/// The error an operation or type verifier reports.
///
/// A message becomes one with `.into()`, and a dialect's own error type with
/// `?`; `downcast_ref` recovers the latter.
pub type VerificationError = Box<dyn Error + Send + Sync>;

/// Operation-local checks the declarative schema cannot express.
///
/// Required for operations declared with `#[verify]`. The generated schema
/// calls it only after every declarative check passed, so typed accessors are
/// safe to use.
#[diagnostic::on_unimplemented(
    message = "`{Self}` is declared with `#[verify]` but does not implement `Verify`",
    label = "`#[verify]` requires this implementation",
    note = "add `impl Verify for {Self} {{ fn verify(&self, ctx: &IrContext) -> Result<(), VerificationError> {{ .. }} }}`"
)]
pub trait Verify: DialectOp {
    fn verify(&self, ctx: &IrContext) -> Result<(), VerificationError>;
}

/// Support for `#[verify]` code generated by the dialect macro.
#[doc(hidden)]
pub mod __private {
    use super::{IrContext, VerificationError, Verify};
    use crate::asm_format::{
        OpAsmFormat, OpAsmFormatDef, OpAsmHooks, TypeAliasHint, TypeAliasHook, TypeAsmFormat,
        TypeAsmHooks, erased_alias_hint,
    };
    use crate::type_def::TypeVerifier;
    use crate::type_verifier::{VerifyType, erased_verifier};

    /// Entry point for generated verifiers. Requiring this instead of
    /// [`Verify`] keeps a missing impl's error from listing every other
    /// `Verify` implementation.
    #[diagnostic::on_unimplemented(
        message = "`{Self}` is declared with `#[verify]` but does not implement `Verify`",
        label = "`#[verify]` requires this implementation",
        note = "add `impl Verify for {Self} {{ fn verify(&self, ctx: &IrContext) -> Result<(), VerificationError> {{ .. }} }}`"
    )]
    pub trait DeclaredVerify {
        fn verify_declared(&self, ctx: &IrContext) -> Result<(), VerificationError>;
    }

    #[diagnostic::do_not_recommend]
    impl<T: Verify> DeclaredVerify for T {
        fn verify_declared(&self, ctx: &IrContext) -> Result<(), VerificationError> {
            self.verify(ctx)
        }
    }

    /// Entry point for generated assembly format hooks, as
    /// [`DeclaredVerify`] is for verifiers.
    #[diagnostic::on_unimplemented(
        message = "`{Self}` is declared with `#[asm_format]` but does not implement `OpAsmFormat`",
        label = "`#[asm_format]` requires this implementation",
        note = "add `impl OpAsmFormat for {Self} {{ fn print(..) {{ .. }} fn parse(..) {{ .. }} }}`"
    )]
    pub trait DeclaredOpAsmFormat {
        const ASM_HOOKS: OpAsmFormatDef;
    }

    #[diagnostic::do_not_recommend]
    impl<T: OpAsmFormat> DeclaredOpAsmFormat for T {
        const ASM_HOOKS: OpAsmFormatDef = OpAsmFormatDef::Hooks(OpAsmHooks {
            print: |h, op| match T::from_op(h.ctx(), op) {
                Ok(op) => op.print(h),
                Err(_) => Err(std::fmt::Error),
            },
            parse: T::parse,
        });
    }

    /// Entry point for generated type verifiers.
    #[diagnostic::on_unimplemented(
        message = "`{Self}` is declared with `#[verify]` but does not implement `VerifyType`",
        label = "`#[verify]` requires this implementation",
        note = "add `impl VerifyType for {Self} {{ fn verify(ctx: &IrContext, ty: TypeRef) -> Result<Self, VerificationError> {{ .. }} }}`"
    )]
    pub trait DeclaredVerifyType {
        const VERIFIER: TypeVerifier;
    }

    #[diagnostic::do_not_recommend]
    impl<T: VerifyType> DeclaredVerifyType for T {
        const VERIFIER: TypeVerifier = erased_verifier::<T>;
    }

    /// Entry point for generated type assembly format hooks.
    #[diagnostic::on_unimplemented(
        message = "`{Self}` is declared with `#[asm_format]` but does not implement `TypeAsmFormat`",
        label = "`#[asm_format]` requires this implementation",
        note = "add `impl TypeAsmFormat for {Self} {{ fn print(..) {{ .. }} fn parse(..) {{ .. }} }}`"
    )]
    pub trait DeclaredTypeAsmFormat {
        const ASM_HOOKS: TypeAsmHooks;
    }

    #[diagnostic::do_not_recommend]
    impl<T: TypeAsmFormat> DeclaredTypeAsmFormat for T {
        const ASM_HOOKS: TypeAsmHooks = TypeAsmHooks::of::<T>();
    }

    /// Entry point for generated type alias name hints.
    #[diagnostic::on_unimplemented(
        message = "`{Self}` is declared with `#[alias_hint]` but does not implement `TypeAliasHint`",
        label = "`#[alias_hint]` requires this implementation",
        note = "add `impl TypeAliasHint for {Self} {{ fn alias_hint<'a>(&self, ctx: &'a IrContext) -> Option<&'a str> {{ .. }} }}`"
    )]
    pub trait DeclaredTypeAliasHint {
        const ALIAS_HINT: TypeAliasHook;
    }

    #[diagnostic::do_not_recommend]
    impl<T: TypeAliasHint> DeclaredTypeAliasHint for T {
        const ALIAS_HINT: TypeAliasHook = erased_alias_hint::<T>;
    }
}

/// Trait for arena-based dialect type wrappers.
pub trait DialectType: Sized + Copy {
    /// Definition generated from the dialect declaration.
    const DEF: &'static TypeDef;
    /// The type's name, which points to [`DEF`](Self::DEF).
    const NAME: TypeName = TypeName::registered(Self::DEF);

    fn from_type_ref(ctx: &IrContext, ty: TypeRef) -> Option<Self>;
    fn as_type_ref(&self) -> TypeRef;

    fn matches(ctx: &IrContext, ty: TypeRef) -> bool {
        ctx.get_type(ty).name == Self::NAME
    }
}
